import{r as e}from"./auth-bgkSYldb.js";var t={list(t=0,n=20,r){return e.get(`/workspaces/current/campaigns`,{params:{page:t,size:n,status:r}})},get(t){return e.get(`/workspaces/current/campaigns/${t}`)},create(t){return e.post(`/workspaces/current/campaigns`,t)},update(t,n){return e.put(`/workspaces/current/campaigns/${t}`,n)},delete(t){return e.delete(`/workspaces/current/campaigns/${t}`)},send(t){return e.post(`/workspaces/current/campaigns/${t}/send`)},pause(t){return e.post(`/workspaces/current/campaigns/${t}/pause`)},resume(t){return e.post(`/workspaces/current/campaigns/${t}/resume`)},cancel(t){return e.post(`/workspaces/current/campaigns/${t}/cancel`)},listMessages(t,n=0,r=20,i){return e.get(`/workspaces/current/campaigns/${t}/messages`,{params:{page:n,size:r,status:i}})},analytics(t){return e.get(`/workspaces/current/campaigns/${t}/analytics`)}};export{t};